'use strict';

/**
 * Generic field parsers. Each parse* returns the normalized value, or null when the input is empty.
 * They throw nothing; callers collect { field, message } details and raise validationFailed once.
 * Use check() to run a parser and record a detail in one step.
 */

const UUID_V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const PAN = /^[A-Z]{5}[0-9]{4}[A-Z]$/;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE = /^[0-9+()\-\s]{5,20}$/;
const DATE = /^(\d{4})-(\d{2})-(\d{2})$/;
const MAX_PAISE = 999999999999; // 9999999999.99 INR

class FieldError extends Error {}

function isUuidV4(value) {
    return typeof value === 'string' && UUID_V4.test(value);
}

/** Trims a string. Empty after trimming, null and undefined give null. Non-strings throw FieldError. */
function normalizeString(value, { min = 0, max = Infinity, label = 'Value' } = {}) {
    if (value === undefined || value === null) return null;
    if (typeof value !== 'string') throw new FieldError(`${label} must be text`);
    const trimmed = value.trim();
    if (trimmed === '') return null;
    if (trimmed.length < min) throw new FieldError(`${label} must be at least ${min} characters`);
    if (trimmed.length > max) throw new FieldError(`${label} must be at most ${max} characters`);
    return trimmed;
}

function parsePan(value) {
    const s = normalizeString(value, { label: 'PAN' });
    if (s === null) return null;
    const upper = s.toUpperCase();
    if (!PAN.test(upper)) throw new FieldError('PAN must be in the format AAAAA9999A');
    return upper;
}

function parseEmail(value) {
    const s = normalizeString(value, { max: 254, label: 'Email' });
    if (s === null) return null;
    if (!EMAIL.test(s)) throw new FieldError('Email is not valid');
    return s.toLowerCase();
}

function parsePhone(value) {
    const s = normalizeString(value, { max: 20, label: 'Phone' });
    if (s === null) return null;
    if (!PHONE.test(s)) throw new FieldError('Phone is not valid');
    return s;
}

/** YYYY-MM-DD that is a real calendar date. */
function parseDate(value) {
    const s = normalizeString(value, { label: 'Date' });
    if (s === null) return null;
    const m = DATE.exec(s);
    if (!m) throw new FieldError('Date must be in the format YYYY-MM-DD');
    const [y, mo, d] = [Number(m[1]), Number(m[2]), Number(m[3])];
    const dt = new Date(Date.UTC(y, mo - 1, d));
    if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) {
        throw new FieldError('Date is not a real date');
    }
    return s;
}

/** INR number with at most 2 decimals, 0..9999999999.99. Returns integer paise. */
function parseMoney(value) {
    if (value === undefined || value === null) return null;
    if (typeof value !== 'number' || !Number.isFinite(value)) throw new FieldError('Amount must be a number');
    const paise = Math.round(value * 100);
    if (Math.abs(value * 100 - paise) > 1e-6) throw new FieldError('Amount can have at most 2 decimal places');
    if (paise < 0 || paise > MAX_PAISE) throw new FieldError('Amount must be between 0 and 9999999999.99');
    return paise;
}

function parseEnum(value, allowed, label = 'Value') {
    const s = normalizeString(value, { label });
    if (s === null) return null;
    if (!allowed.includes(s)) throw new FieldError(`${label} must be one of ${allowed.join(', ')}`);
    return s;
}

/** Today's date (YYYY-MM-DD) in Asia/Kolkata. */
function todayIst(now = new Date()) {
    return new Intl.DateTimeFormat('en-CA', {
        timeZone: 'Asia/Kolkata',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
    }).format(now);
}

function toInr(paise) {
    return paise === null || paise === undefined ? null : paise / 100;
}

function nameSort(name, id) {
    return `${String(name).trim().toLowerCase()}#${id}`;
}

/**
 * Runs parse(value) and returns its result. On FieldError pushes { field, message } into details
 * and returns undefined. When required and the result is null, records "<label> is required".
 */
function check(details, field, parse, { required = false, requiredMessage } = {}) {
    try {
        const result = parse();
        if (required && result === null) {
            details.push({ field, message: requiredMessage || `${field} is required` });
            return undefined;
        }
        return result;
    } catch (err) {
        if (!(err instanceof FieldError)) throw err;
        details.push({ field, message: err.message });
        return undefined;
    }
}

module.exports = {
    FieldError,
    isUuidV4,
    normalizeString,
    parsePan,
    parseEmail,
    parsePhone,
    parseDate,
    parseMoney,
    parseEnum,
    todayIst,
    toInr,
    nameSort,
    check,
};
